// Authored speeds of the clip set (cm/s per clip, matched to the planted-foot speed so feet do not slide).
static float ClipSpeed(FName N)
{
	static const TMap<FName, float> Speeds = {
		{ TEXT("walk"), 96.f }, { TEXT("walk_limp"), 90.f }, { TEXT("drag_rescuer"), 90.f }, { TEXT("carry_crate"), 100.f }, { TEXT("wounded_crawl"), 30.f }, { TEXT("prone_crawl"), 40.f }, { TEXT("run"), 529.f }, { TEXT("sprint"), 814.f }, { TEXT("walk_formal"), 96.f },
		{ TEXT("aim_walk_fwd"), 130.f }, { TEXT("aim_walk_bwd"), 110.f }, { TEXT("aim_strafe_l"), 120.f }, { TEXT("aim_strafe_r"), 120.f },
		{ TEXT("crouch_walk"), 74.f }, { TEXT("tiptoe_walk"), 70.f }, { TEXT("saber_run"), 420.f } };
	const float* V = Speeds.Find(N);
	return V ? *V : 0.f;
}
static void CopyPose(FPoseContext& Out, FPoseContext& Src)
{
	Out.Pose.CopyBonesFrom(Src.Pose);
	Out.Curve.CopyFrom(Src.Curve);
}
static bool IsFullBodyAction(FName N)
{
	// motion-capture performances (lightsaber strikes, Force moves, ignite) are whole-body by nature
	const FString S = N.ToString();
	if (S.StartsWith(TEXT("saber_strike_")) || S.StartsWith(TEXT("sw_")) || S.StartsWith(TEXT("sword_"))) return true;
	return N == TEXT("hit_front") || N == TEXT("hit_back") || N == TEXT("melee") || N == TEXT("jump") ||
		N == TEXT("roll_to_kneel") || N == TEXT("mantle") || N == TEXT("saber_hit_1") || N == TEXT("saber_hit_2") ||
		N == TEXT("getup_back") || N == TEXT("getup_front") || N == TEXT("go_prone") || N == TEXT("dive_left") || N == TEXT("dive_right") ||
		N == TEXT("vault") || N == TEXT("turn_l90") || N == TEXT("turn_r90") || N == TEXT("run_stop") || N == TEXT("flinch_duck") ||
		N == TEXT("hit_left") || N == TEXT("hit_right") || N == TEXT("tiptoe_peek") ||
		N == TEXT("saber_attack_1") || N == TEXT("saber_attack_2") || N == TEXT("saber_attack_3") || N == TEXT("saber_thrust") || N == TEXT("cover_low_fire") || N == TEXT("cover_lean_fire_r") || N == TEXT("cover_lean_fire_l");
}

float UDukeTrooperAnimInstance::ClipLength(FName Name) const
{
	const TObjectPtr<UAnimSequence>* A = Clips.Find(Name);
	return (A && *A) ? (*A)->GetPlayLength() : 0.f;
}

const FName UDukeTrooperAnimInstance::MontageSlot(TEXT("DefaultSlot"));

int32 UDukeTrooperAnimInstance::LoadClipSet(UDukeTrooperAnimInstance* A, const FString& AssetPath, const TArray<FName>& Fallback)
{
	if (!A) return 0;
	IAssetRegistry& AR = FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get();
	TArray<FAssetData> Found; AR.GetAssetsByPath(FName(*(AssetPath + TEXT("/Anims"))), Found, true);
	for (const FAssetData& D : Found)
	{
		FString N = D.AssetName.ToString();
		if (!N.RemoveFromStart(TEXT("A_Trooper_"))) continue;
		if (UAnimSequence* Seq = Cast<UAnimSequence>(D.GetAsset())) A->Clips.Add(FName(*N), Seq);
	}
	for (const FName& N : Fallback)
		if (!A->Clips.Contains(N))
			if (UAnimSequence* Seq = LoadObject<UAnimSequence>(nullptr, *FString::Printf(TEXT("%s/Anims/A_Trooper_%s.A_Trooper_%s"), *AssetPath, *N.ToString(), *N.ToString()))) A->Clips.Add(N, Seq);
	return A->Clips.Num();
}

void FDukeTrooperAnimProxy::Initialize(UAnimInstance* InAnimInstance)
{
	FAnimInstanceProxy::Initialize(InAnimInstance);
	RegisterSlot(UDukeTrooperAnimInstance::MontageSlot);
}

void FDukeTrooperAnimProxy::PreUpdate(UAnimInstance* InAnimInstance, float DeltaSeconds)
{
	FAnimInstanceProxy::PreUpdate(InAnimInstance, DeltaSeconds);
	const UDukeTrooperAnimInstance* I = CastChecked<UDukeTrooperAnimInstance>(InAnimInstance);
	Clips.Reset();
	for (const TPair<FName, TObjectPtr<UAnimSequence>>& P : I->Clips)
		if (P.Value) Clips.Add(P.Key, P.Value.Get());
	S = I->State;
}

const UAnimSequence* FDukeTrooperAnimProxy::Clip(FName N) const
{
	const UAnimSequence* const* A = Clips.Find(N);
	return A ? *A : nullptr;
}

void FDukeTrooperAnimProxy::BuildBase(TArray<FDukeClipRef>& Out, FName& OutKey)
{
	Out.Reset();
	const float Speed = S.LocalVelocity.Size2D();
	auto Add = [&](FName N, float W, float Time, bool bLoop = true)
	{
		if (W <= 0.001f) return;
		if (const UAnimSequence* Q = Clip(N)) Out.Add({ Q, Time, W, bLoop });
	};
	auto Cyc = [&](FName N) { const UAnimSequence* Q = Clip(N); return Q ? GaitPhase * Q->GetPlayLength() : 0.f; };

	if (S.bDead)
	{
		const FName Death = (S.DeathClip != NAME_None && Clip(S.DeathClip)) ? S.DeathClip : FName(TEXT("die"));
		OutKey = Death;
		Add(Death, 1.f, S.DeathTime, false);
		return;
	}
	if (S.bDragged) { OutKey = TEXT("drag_wounded"); Add(TEXT("drag_wounded"), 1.f, Cyc(TEXT("drag_rescuer"))); return; }
	if (S.bWounded)
	{
		if (Speed > 10.f) { OutKey = TEXT("wounded_crawl"); Add(TEXT("wounded_crawl"), 1.f, Cyc(TEXT("wounded_crawl"))); }
		else { OutKey = TEXT("wounded_down"); Add(TEXT("wounded_down"), 1.f, IdleTime); }
		return;
	}
	if (S.bProne)
	{
		if (Speed > 10.f) { OutKey = TEXT("prone_crawl"); Add(TEXT("prone_crawl"), 1.f, Cyc(TEXT("prone_crawl"))); }
		else { OutKey = TEXT("prone_aim"); Add(TEXT("prone_aim"), 1.f, IdleTime); }
		return;
	}
	if (S.bDragging) { OutKey = TEXT("drag_rescuer"); Add(TEXT("drag_rescuer"), 1.f, Cyc(TEXT("drag_rescuer"))); return; }
	if (S.DutyClip != NAME_None && Clip(S.DutyClip))
	{
		// moving duties (carry_crate) cycle with the gait; standing duties loop on their own clock
		OutKey = S.DutyClip;
		Add(S.DutyClip, 1.f, ClipSpeed(S.DutyClip) > 1.f ? Cyc(S.DutyClip) : IdleTime, true);
		return;
	}
	if (S.bClimbing)
	{
		OutKey = TEXT("climb_ladder");
		const UAnimSequence* Q = Clip(TEXT("climb_ladder"));
		Add(TEXT("climb_ladder"), 1.f, Q ? ClimbPhase * Q->GetPlayLength() : 0.f);
		return;
	}
	if (S.bKneeling)
	{
		OutKey = TEXT("kneel_aim");
		Add(TEXT("kneel_aim"), 1.f, IdleTime);
		return;
	}
	if (S.bFalling)
	{
		OutKey = TEXT("jump");
		Add(TEXT("jump"), 1.f, FMath::Min(StateTime + 0.2f, 0.5f), false);
		return;
	}
	if (S.bCrouched)
	{
		if (Speed > 25.f) { OutKey = TEXT("crouch_walk"); Add(TEXT("crouch_walk"), 1.f, Cyc(TEXT("crouch_walk"))); }
		else { OutKey = TEXT("crouch_aim"); Add(TEXT("crouch_aim"), 1.f, IdleTime); }
		return;
	}
	if (S.bAiming)
	{
		if (Speed < 25.f) { OutKey = TEXT("aim"); Add(TEXT("aim"), 1.f, IdleTime); return; }
		// Jedi charging with the blade lit: forward run past walking speed (the aim walks would slide)
		if (Speed > 240.f && S.LocalVelocity.X > FMath::Abs(S.LocalVelocity.Y) && Clip(TEXT("saber_run")))
		{
			OutKey = TEXT("saber_run"); Add(TEXT("saber_run"), 1.f, Cyc(TEXT("saber_run"))); return;
		}
		// direction blend: forward / right / back / left around the circle, two neighbours at a time
		OutKey = TEXT("aim_move");
		const float Ang = FMath::RadiansToDegrees(FMath::Atan2(S.LocalVelocity.Y, S.LocalVelocity.X)); // 0 fwd, +90 right
		static const FName Dir[4] = { TEXT("aim_walk_fwd"), TEXT("aim_strafe_r"), TEXT("aim_walk_bwd"), TEXT("aim_strafe_l") };
		const float A = FMath::Fmod(Ang + 360.f, 360.f) / 90.f;
		const int32 I0 = FMath::FloorToInt(A) % 4, I1 = (I0 + 1) % 4;
		const float T = A - FMath::FloorToFloat(A);
		const float Ramp = FMath::Clamp((Speed - 25.f) / 60.f, 0.f, 1.f);
		Add(TEXT("aim"), 1.f - Ramp, IdleTime);
		Add(Dir[I0], Ramp * (1.f - T), Cyc(Dir[I0]));
		Add(Dir[I1], Ramp * T, Cyc(Dir[I1]));
		return;
	}
	if (Speed < 25.f)
	{
		const FName Idle = (S.IdleVariant != NAME_None && Clip(S.IdleVariant)) ? S.IdleVariant : FName(TEXT("idle"));
		OutKey = Idle;
		Add(Idle, 1.f, IdleTime);
		return;
	}
	if (S.bLimping)
	{
		OutKey = TEXT("limp");
		const float Ramp = FMath::Clamp((Speed - 25.f) / 60.f, 0.f, 1.f);
		Add(TEXT("idle"), 1.f - Ramp, IdleTime);
		Add(TEXT("walk_limp"), Ramp, Cyc(TEXT("walk_limp")));
		return;
	}
	OutKey = TEXT("move");
	// walk -> run -> sprint by speed, all phase-locked
	const float W2R = FMath::Clamp((Speed - 200.f) / 150.f, 0.f, 1.f);
	const float R2S = FMath::Clamp((Speed - 600.f) / 150.f, 0.f, 1.f);   // captured run 5.3 m/s, sprint 8.1 m/s
	const float Ramp = FMath::Clamp((Speed - 25.f) / 60.f, 0.f, 1.f);
	Add(TEXT("idle"), 1.f - Ramp, IdleTime);
	const FName WalkClip = (S.bSneak && Clip(TEXT("tiptoe_walk"))) ? FName(TEXT("tiptoe_walk")) : FName(TEXT("walk"));
	Add(WalkClip, Ramp * (1.f - W2R), Cyc(WalkClip));
	Add(TEXT("run"), Ramp * W2R * (1.f - R2S), Cyc(TEXT("run")));
	Add(TEXT("sprint"), Ramp * R2S, Cyc(TEXT("sprint")));
}

void FDukeTrooperAnimProxy::Update(float DeltaSeconds)
{
	FAnimInstanceProxy::Update(DeltaSeconds);
	Dt = DeltaSeconds;
	GetSlotWeight(UDukeTrooperAnimInstance::MontageSlot, SlotNodeWeight, SlotSourceWeight, SlotTotalWeight);
	UpdateSlotNodeWeight(UDukeTrooperAnimInstance::MontageSlot, SlotNodeWeight, 1.f);
	IdleTime += Dt; StateTime += Dt;
	if (S.bDead) DeadTime += Dt; else DeadTime = 0.f;
	if (const UAnimSequence* C = Clip(TEXT("climb_ladder")))   // authored at 50 cm/s
		ClimbPhase = FMath::Fmod(ClimbPhase + Dt * (S.ClimbSpeed / 50.f) / FMath::Max(C->GetPlayLength(), 0.01f) + 1.f, 1.f);

	// advance the shared gait phase by the dominant locomotion clip's authored speed, so feet stay planted
	const float Speed = S.LocalVelocity.Size2D();
	FName Gait = TEXT("walk");
	if (S.bCrouched) Gait = TEXT("crouch_walk");
	else if (S.bAiming && Speed > 240.f && S.LocalVelocity.X > FMath::Abs(S.LocalVelocity.Y) && Clip(TEXT("saber_run"))) Gait = TEXT("saber_run");
	else if (S.bAiming) Gait = FMath::Abs(S.LocalVelocity.Y) > FMath::Abs(S.LocalVelocity.X) ? FName(S.LocalVelocity.Y > 0 ? TEXT("aim_strafe_r") : TEXT("aim_strafe_l")) : FName(S.LocalVelocity.X >= 0 ? TEXT("aim_walk_fwd") : TEXT("aim_walk_bwd"));
	else if (S.bLimping) Gait = TEXT("walk_limp");
	else if (S.bSneak) Gait = TEXT("tiptoe_walk");
	if (S.bDragging || S.bDragged) Gait = TEXT("drag_rescuer");      // the pair shares one clock, so hands and collar stay together
	else if (S.bWounded) Gait = TEXT("wounded_crawl");
	else if (S.bProne) Gait = TEXT("prone_crawl");
	else if (S.DutyClip == TEXT("carry_crate")) Gait = TEXT("carry_crate");
	else if (Speed > 525.f) Gait = TEXT("sprint");
	else if (Speed > 275.f) Gait = TEXT("run");
	if (const UAnimSequence* G = Clip(Gait))
	{
		const float Authored = ClipSpeed(Gait);
		const float Rate = Authored > 1.f ? FMath::Clamp(Speed / Authored, 0.5f, 1.6f) : 1.f;
		GaitPhase = FMath::Fmod(GaitPhase + Dt * Rate / FMath::Max(G->GetPlayLength(), 0.01f), 1.f);
	}

	TArray<FDukeClipRef> NewBase; FName NewKey;
	BuildBase(NewBase, NewKey);
	if (NewKey != BaseKey)
	{
		PrevBase = Base; BaseFade = 0.f; BaseKey = NewKey; StateTime = 0.f;
		if (NewKey != TEXT("move") && NewKey != TEXT("aim_move")) IdleTime = 0.f;
		BuildBase(NewBase, NewKey);
	}
	const float FadeTime = S.bDead ? 0.12f : 0.22f;
	BaseFade = FMath::Min(1.f, BaseFade + Dt / FadeTime);
	Base = NewBase;

	// action layer: restart on a new serial, fade in fast, fade out near the end
	if (S.ActionSerial != ActionSerial)
	{
		ActionSerial = S.ActionSerial; ActionName = S.Action; ActionTime = 0.f;
	}
	if (const UAnimSequence* A = (ActionName != NAME_None && !S.bDead) ? Clip(ActionName) : nullptr)
	{
		ActionTime += Dt * S.ActionRate;
		const float Len = A->GetPlayLength();
		const float In = FMath::Clamp(ActionTime / 0.06f, 0.f, 1.f);
		const float Out = FMath::Clamp((Len - ActionTime) / 0.15f, 0.f, 1.f);
		ActionWeight = FMath::Min(In, Out);
		if (ActionTime >= Len) { ActionName = NAME_None; ActionWeight = 0.f; }
	}
	else
	{
		ActionWeight = 0.f;
	}
}

void FDukeTrooperAnimProxy::Sample(const UAnimSequence* Seq, float Time, bool bLoop, FPoseContext& Out)
{
	const float Len = Seq->GetPlayLength();
	const float T = bLoop && Len > 0.f ? FMath::Fmod(Time, Len) : FMath::Clamp(Time, 0.f, Len);
	FAnimationPoseData PoseData(Out);
	FAnimExtractContext Ctx(static_cast<double>(T), false, FDeltaTimeRecord(), bLoop);
	Seq->GetAnimationPose(PoseData, Ctx);
}

void FDukeTrooperAnimProxy::SampleLayer(const TArray<FDukeClipRef>& Layer, FPoseContext& Out) const
{
	float Total = 0.f;
	for (const FDukeClipRef& C : Layer) Total += C.Weight;
	if (Layer.Num() == 0 || Total <= 0.f) { Out.ResetToRefPose(); return; }
	Sample(Layer[0].Seq, Layer[0].Time, Layer[0].bLoop, Out);
	float Acc = Layer[0].Weight;
	for (int32 i = 1; i < Layer.Num(); ++i)
	{
		FPoseContext Next(Out);
		Sample(Layer[i].Seq, Layer[i].Time, Layer[i].bLoop, Next);
		Acc += Layer[i].Weight;
		const float WNext = Layer[i].Weight / Acc;
		FPoseContext Mixed(Out);
		FAnimationPoseData A(Out), B(Next), M(Mixed);
		FAnimationRuntime::BlendTwoPosesTogether(A, B, 1.f - WNext, M);
		CopyPose(Out, Mixed);
	}
}

void FDukeTrooperAnimProxy::BlendUpper(FPoseContext& Out, const FPoseContext& Upper, float Weight) const
{
	if (Weight <= 0.f) return;
	const FBoneContainer& BC = Out.Pose.GetBoneContainer();
	const FReferenceSkeleton& Ref = BC.GetReferenceSkeleton();
	const int32 Spine = Ref.FindBoneIndex(TEXT("spine_01"));
	for (FCompactPoseBoneIndex B : Out.Pose.ForEachBoneIndex())
	{
		const int32 MeshIdx = BC.MakeMeshPoseIndex(B).GetInt();
		bool bUpper = false;
		for (int32 P = MeshIdx; P != INDEX_NONE; P = Ref.GetParentIndex(P))
			if (P == Spine) { bUpper = true; break; }
		if (!bUpper) continue;
		FTransform T = Out.Pose[B];
		T.BlendWith(Upper.Pose[B], Weight);
		T.NormalizeRotation();
		Out.Pose[B] = T;
	}
}

bool FDukeTrooperAnimProxy::Evaluate(FPoseContext& Output)
{
	if (Base.Num() == 0) { Output.ResetToRefPose(); return true; }
	SampleLayer(Base, Output);
	if (BaseFade < 1.f && PrevBase.Num() > 0)
	{
		FPoseContext Prev(Output), Mixed(Output);
		SampleLayer(PrevBase, Prev);
		FAnimationPoseData A(Prev), B(Output), M(Mixed);
		const float Alpha = BaseFade * BaseFade * (3.f - 2.f * BaseFade);
		FAnimationRuntime::BlendTwoPosesTogether(A, B, 1.f - Alpha, M);
		CopyPose(Output, Mixed);
	}
	// aim pitch: upper body toward aim_up / aim_down while the rifle is shouldered
	if ((S.bAiming || S.bCrouched) && !S.bDead && FMath::Abs(S.AimPitch) > 1.f)
	{
		const FName Pose = S.AimPitch > 0.f ? FName(TEXT("aim_up")) : FName(TEXT("aim_down"));
		if (const UAnimSequence* Q = Clip(Pose))
		{
			FPoseContext P(Output);
			Sample(Q, 0.f, false, P);
			BlendUpper(Output, P, FMath::Clamp(FMath::Abs(S.AimPitch) / 50.f, 0.f, 1.f));
		}
	}
	// action layer: upper body while moving, full body when standing still (or for full-body actions)
	if (ActionWeight > 0.f && ActionName != NAME_None)
	{
		FName Name = ActionName;
		if (S.bCrouched && (Name == TEXT("shoot") || Name == TEXT("shoot_burst")) && Clip(TEXT("crouch_shoot"))) Name = TEXT("crouch_shoot");
		if (S.bKneeling && (Name == TEXT("shoot") || Name == TEXT("shoot_burst")) && Clip(TEXT("kneel_shoot"))) Name = TEXT("kneel_shoot");
		if (S.bProne && (Name == TEXT("shoot") || Name == TEXT("shoot_burst")) && Clip(TEXT("prone_shoot"))) Name = TEXT("prone_shoot");
		if (const UAnimSequence* Q = Clip(Name))
		{
			FPoseContext P(Output);
			Sample(Q, ActionTime, false, P);
			if (Name.ToString().StartsWith(TEXT("saber_strike_")))   // capture strikes carry travel on the root: on the action layer (no root
			{                                                          // motion) keep it under the capsule instead of drifting and snapping back
				FTransform& R0 = P.Pose[FCompactPoseBoneIndex(0)]; const FVector L = R0.GetTranslation(); R0.SetTranslation(FVector(0.f, 0.f, L.Z));
			}
			const bool bStill = S.LocalVelocity.Size2D() < 25.f && !S.bFalling;
			if (bStill || IsFullBodyAction(Name))
			{
				FPoseContext Mixed(Output);
				FAnimationPoseData A(Output), B(P), M(Mixed);
				FAnimationRuntime::BlendTwoPosesTogether(A, B, 1.f - ActionWeight, M);
				CopyPose(Output, Mixed);
			}
			else
			{
				BlendUpper(Output, P, ActionWeight);
			}
		}
	}
	// montage slot over everything above (root-motion attacks, motion-warped strikes)
	if (SlotNodeWeight > ZERO_ANIMWEIGHT_THRESH)
	{
		FPoseContext Blended(Output);
		FAnimationPoseData Src(Output), Dst(Blended);
		SlotEvaluatePose(UDukeTrooperAnimInstance::MontageSlot, Src, SlotSourceWeight, Dst, SlotNodeWeight, SlotTotalWeight);
		CopyPose(Output, Blended);
	}
	ApplyLook(Output);
	ApplyProcedural(Output);
	return true;
}

void FDukeTrooperAnimProxy::ApplyProcedural(FPoseContext& Out) const
{
	if (S.bDead || S.ProceduralBones.Num() == 0) return;
	const FBoneContainer& BC = Out.Pose.GetBoneContainer();
	TArray<TPair<FCompactPoseBoneIndex, FQuat>, TInlineAllocator<12>> Todo;
	const FQuat ToComp = S.MeshToActor.Inverse();
	for (const FDukeBoneOffset& O : S.ProceduralBones)
	{
		if (O.Rotation.Equals(FQuat::Identity, 1e-4f)) continue;
		const int32 Mesh = BC.GetPoseBoneIndexForBoneName(O.Bone); if (Mesh == INDEX_NONE) continue;
		const FCompactPoseBoneIndex B = BC.MakeCompactPoseIndex(FMeshPoseBoneIndex(Mesh)); if (!B.IsValid()) continue;
		Todo.Add({ B, ToComp * O.Rotation * S.MeshToActor });   // actor-space delta -> component space
	}
	if (Todo.Num() == 0) return;
	Todo.Sort([](const auto& A, const auto& B) { return A.Key < B.Key; });   // compact order: parents before children
	FCSPose<FCompactPose> CS; CS.InitPose(Out.Pose);
	for (const auto& T : Todo)
	{
		FTransform X = CS.GetComponentSpaceTransform(T.Key);   // includes the deltas already applied to its parents
		X.SetRotation((T.Value * X.GetRotation()).GetNormalized());
		CS.SetComponentSpaceTransform(T.Key, X);              // children follow
	}
	FCSPose<FCompactPose>::ConvertComponentPosesToLocalPoses(MoveTemp(CS), Out.Pose);
}

// Head look: neck_01, head and (for yaw) spine_03 get the local-space delta of the look_* pose against the neutral
// look_around frame 0, scaled by the requested angle (look poses are authored at ~56 deg yaw, ~42 deg pitch).
void FDukeTrooperAnimProxy::ApplyLook(FPoseContext& Out) const
{
	if (S.bDead || S.bAiming || (FMath::Abs(S.LookYaw) < 0.5f && FMath::Abs(S.LookPitch) < 0.5f)) return;
	const UAnimSequence* Neutral = Clip(TEXT("look_around")); if (!Neutral) return;
	FPoseContext N(Out); Sample(Neutral, 0.f, false, N);
	const FBoneContainer& BC = Out.Pose.GetBoneContainer();
	auto Add = [&](FName PoseName, float W)
	{
		const UAnimSequence* Q = Clip(PoseName); if (!Q || W <= 0.f) return;
		FPoseContext L(Out); Sample(Q, 0.f, false, L);
		for (const TCHAR* Bone : { TEXT("spine_03"), TEXT("neck_01"), TEXT("head") })
		{
			const int32 Mesh = BC.GetPoseBoneIndexForBoneName(Bone); if (Mesh == INDEX_NONE) continue;
			const FCompactPoseBoneIndex B = BC.MakeCompactPoseIndex(FMeshPoseBoneIndex(Mesh)); if (!B.IsValid()) continue;
			const FQuat Delta = N.Pose[B].GetRotation().Inverse() * L.Pose[B].GetRotation();
			Out.Pose[B].SetRotation((Out.Pose[B].GetRotation() * FQuat::Slerp(FQuat::Identity, Delta, W)).GetNormalized());
		}
	};
	Add(S.LookYaw > 0.f ? FName(TEXT("look_right")) : FName(TEXT("look_left")), FMath::Clamp(FMath::Abs(S.LookYaw) / 56.f, 0.f, 1.4f));
	Add(S.LookPitch > 0.f ? FName(TEXT("look_up")) : FName(TEXT("look_down")), FMath::Clamp(FMath::Abs(S.LookPitch) / 42.f, 0.f, 1.2f));
}
